import heapq


def _interval_solver(capacity, tie):
    def solve(data):
        jobs = data["jobs"]
        k = data["k"]
        blocked = set(data.get("blocked", []))
        mandatory = set(data.get("mandatory", []))
        if mandatory & blocked or len(mandatory) > k:
            return {"error": "impossible"}
        options = [job for job in jobs if job["id"] not in blocked]
        quotas = data.get("quotas", {})
        best_value = None
        best_ids = None

        for subset in combinations(options, k):
            ids = {job["id"] for job in subset}
            if not mandatory.issubset(ids):
                continue
            counts = {}
            for job in subset:
                counts[job["group"]] = counts.get(job["group"], 0) + 1
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in quotas.items()):
                continue
            active = []
            valid = True
            for job in sorted(subset, key=lambda row: (row["start"], row["end"])):
                while active and active[0] <= job["start"]:
                    heapq.heappop(active)
                heapq.heappush(active, job["end"])
                if len(active) > capacity:
                    valid = False
                    break
            if not valid:
                continue
            value = sum(job["value"] for job in subset)
            selected = sorted(ids)
            if (best_value is None or value > best_value or
                    (value == best_value and
                     ((tie == "largest" and selected > best_ids) or
                      (tie == "smallest" and selected < best_ids)))):
                best_value, best_ids = value, selected

        if best_value is None:
            return {"error": "impossible"}
        return {"selected": best_ids, "value": best_value}
    return solve


def _build_component_06():
    def rounded(numerator, denominator, mode):
        if mode == "half_up":
            return (2 * numerator + denominator) // (2 * denominator)
        return numerator // denominator

    def amount(event, mode):
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount), 10000, mode)
        tax = rounded(raw * event.get("tax_bp", 0), 10000, mode)
        total = net + tax
        return -total if event.get("kind") == "refund" else total

    def solve(data):
        cutoff = data.get("cutoff", 10**9)
        chosen = {}
        for position, event in enumerate(data["events"]):
            if event.get("sequence", 0) > cutoff:
                continue
            event_id = event.get("id", "anonymous:" + str(position))
            key = (event.get("revision", 0), position)
            if event_id not in chosen or key > chosen[event_id][0]:
                chosen[event_id] = (key, event)

        balances = dict(data.get("opening", {}))
        for _, event in chosen.values():
            if event.get("void", False):
                continue
            key = str(event.get("account", "default")) + "|" + str(event.get("currency", "USD"))
            balances[key] = balances.get(key, 0) + amount(event, data["rounding"])
        return {"balances": balances}
    return solve


def _build_component_07():
    def solve(data):
        packages = data["packages"]
        names = sorted(packages, reverse=True)
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        roots = data["roots"]

        choices = []
        for name in names:
            rows = packages[name]
            versions = sorted({row["version"] for row in rows})
            allowed = [version for version in versions
                       if version not in blocked.get(name, [])
                       and (name not in pins or version == pins[name])]
            choices.append([None] + allowed)

        best_vector = None
        best_versions = None
        for assignment in product(*choices):
            selected = {name: version for name, version in zip(names, assignment)
                        if version is not None}
            if any(name not in selected or not low <= selected[name] <= high
                   for name, (low, high) in roots.items()):
                continue

            edges = {name: [] for name in selected}
            valid = True
            for name, version in selected.items():
                row = next(row for row in packages[name] if row["version"] == version)
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    target = dep["name"]
                    target_version = selected.get(target)
                    if target_version is None or not dep["min"] <= target_version <= dep["max"]:
                        valid = False
                        break
                    edges[name].append(target)
                if not valid:
                    break
            if not valid:
                continue

            state = {}
            def visit(name):
                if state.get(name) == 1:
                    return False
                if state.get(name) == 2:
                    return True
                state[name] = 1
                for other in edges[name]:
                    if not visit(other):
                        return False
                state[name] = 2
                return True

            if not all(visit(name) for name in edges):
                continue

            reachable = set()
            stack = list(roots)
            while stack:
                name = stack.pop()
                if name in reachable:
                    continue
                reachable.add(name)
                stack.extend(edges[name])
            if reachable != set(selected):
                continue

            vector = tuple(selected.get(name, -1) for name in names)
            if best_vector is None or vector < best_vector:
                best_vector = vector
                best_versions = selected

        if best_versions is None:
            return {"error": "unsatisfiable"}
        return {"versions": best_versions}
    return solve


def _build_component_08():
    def solve(data):
        required = data.get("required", [])
        full_mask = (1 << len(required)) - 1

        def visit_mask(node):
            mask = 0
            for i, required_node in enumerate(required):
                if node == required_node:
                    mask |= 1 << i
            return mask

        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)

        source = data["source"]
        initial = (source, visit_mask(source), data["coupons"])
        distances = {initial: data["start"]}
        queue = [(data["start"], source, initial[1], data["coupons"])]
        while queue:
            time, node, mask, coupons_left = heapq.heappop(queue)
            state = (node, mask, coupons_left)
            if distances.get(state) != time:
                continue
            if node == data["target"] and mask == full_mask:
                return {"arrival": time}

            for edge in graph[node]:
                depart = max(time, edge["open"])
                if depart >= edge["close"]:
                    continue
                options = [(edge["duration"], coupons_left)]
                if coupons_left:
                    options.append((max(1, edge["duration"] - edge.get("discount", 0)), coupons_left - 1))
                for duration, remaining in options:
                    arrival = depart + duration
                    if arrival > data["deadline"]:
                        continue
                    next_node = edge["v"]
                    next_mask = mask | visit_mask(next_node)
                    next_state = (next_node, next_mask, remaining)
                    if arrival < distances.get(next_state, float("inf")):
                        distances[next_state] = arrival
                        heapq.heappush(queue, (arrival, next_node, next_mask, remaining))
        return {"arrival": None}
    return solve


